import { Group, Mesh, Shape, ExtrudeGeometry, PlaneGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, Color, DoubleSide } from 'three/webgpu';
import { uv, vec2, smoothstep, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

const INK = '#16161d';
const PAPER = '#e8ecf2';
const ACCENT = '#ff2a38';
const SURFACE = '#0b0b10';

function roundedRectShape(w, h, r) {
  const shape = new Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + h - r);
  shape.quadraticCurveTo(x, y + h, x + r, y + h);
  shape.lineTo(x + w - r, y + h);
  shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  shape.lineTo(x + w, y + r);
  shape.quadraticCurveTo(x + w, y, x + w - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'journal-quote-panel';

  const disposables = [];
  const cleanupFns = [];
  const timelines = [];

  // ---- Card body (extruded, bevelled — never a flat rect) ----
  const cardW = 2.4;
  const cardH = 1.5;
  const cardDepth = 0.1;
  const shape = roundedRectShape(cardW, cardH, 0.08);
  const extrudeSettings = {
    depth: cardDepth,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 8,
  };
  const cardGeo = new ExtrudeGeometry(shape, extrudeSettings);
  cardGeo.translate(0, 0, -cardDepth / 2);
  disposables.push(cardGeo);

  const cardMat = new MeshStandardNodeMaterial({
    color: new Color(INK),
    roughness: 0.62,
    metalness: 0.28,
  });
  disposables.push(cardMat);

  const cardMesh = new Mesh(cardGeo, cardMat);
  root.add(cardMesh);

  // ---- Accent edge trim (left spine, glows on focus) ----
  const edgeGeo = new PlaneGeometry(0.05, cardH * 0.86);
  disposables.push(edgeGeo);
  const focusUniform = uniform(0.18);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(ACCENT),
    roughness: 0.5,
    metalness: 0.3,
    side: DoubleSide,
  });
  edgeMat.emissiveNode = color(ACCENT).mul(focusUniform);
  disposables.push(edgeMat);
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(-cardW / 2 + 0.03, 0, cardDepth / 2 + 0.001);
  root.add(edgeMesh);

  // ---- Image inset (feature card art) ----
  const insetW = cardW - 0.4;
  const insetH = 0.62;
  const insetGeo = new PlaneGeometry(insetW, insetH);
  disposables.push(insetGeo);
  const insetMat = new MeshStandardNodeMaterial({
    color: new Color(SURFACE),
    roughness: 0.55,
    metalness: 0.12,
  });
  disposables.push(insetMat);
  const insetMesh = new Mesh(insetGeo, insetMat);
  insetMesh.position.set(0.06, cardH / 2 - insetH / 2 - 0.16, cardDepth / 2 + 0.005);
  root.add(insetMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      insetMat.map = tex;
      insetMat.needsUpdate = true;
    });
  }

  // ---- Ornamental quote mark (foreground accent, small area) ----
  const glyph = ctx.fontAtlas.createText('"', {
    fontSize: 96,
    color: ACCENT,
    align: 'left',
  });
  glyph.position.set(-cardW / 2 + 0.14, cardH / 2 - insetH - 0.1, cardDepth / 2 + 0.02);
  root.add(glyph);

  // ---- Text content (quote + attribution) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const quoteItem = items.find((i) => /quote|body/i.test(i.role || '')) || items[0];
  const attribItem = items.find((i) => /attrib|caption|label/i.test(i.role || '')) || items[1];

  const textGroup = new Group();
  root.add(textGroup);

  if (quoteItem && quoteItem.text) {
    const quoteText = ctx.fontAtlas.createText(quoteItem.text, {
      fontSize: quoteItem.typography?.fontSize ?? 34,
      color: PAPER,
      align: 'left',
      maxWidthPx: (insetW - 0.1) * 260,
    });
    quoteText.position.set(-insetW / 2 + 0.06, -0.08, cardDepth / 2 + 0.02);
    textGroup.add(quoteText);
  }

  if (attribItem && attribItem.text) {
    const attribText = ctx.fontAtlas.createText(attribItem.text.toUpperCase(), {
      fontSize: attribItem.typography?.fontSize ?? 16,
      color: ACCENT,
      align: 'left',
      letterSpacingPx: 1.4,
    });
    attribText.position.set(-insetW / 2 + 0.06, -cardH / 2 + 0.16, cardDepth / 2 + 0.02);
    textGroup.add(attribText);
  }

  // ---- Contact shadow (radial, grounded) ----
  const shadowRadius = 1.35 * (cardW / 2);
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  disposables.push(shadowGeo);
  const distFromCenter = uv().sub(vec2(0.5, 0.5)).length();
  const shadowAlpha = smoothstep(0.5, 0.1, distFromCenter).mul(0.45);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = shadowAlpha;
  disposables.push(shadowMat);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardH / 2 - 0.32, -cardDepth);
  root.add(shadowMesh);

  // ---- Local rim light (accent hue, capped intensity) ----
  const rimLight = new DirectionalLight(new Color(ACCENT), 0.65);
  rimLight.position.set(-1.2, 0.6, 1.4);
  root.add(rimLight);
  root.add(rimLight.target);

  // ---- Cinematic primitives ----
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const result = fn(root, prim.params ?? {});
      if (result?.cleanup) cleanupFns.push(result.cleanup);
    }
  }

  // ---- Entrance: weighted settle ----
  root.scale.set(0.96, 0.96, 0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.5,
    ease: 'power2.out',
  }).to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.4,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // ---- Interaction handlers ----
  let hoverTl = null;
  const onPointerEnter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: '+=0.15', duration: 0.3, ease: 'power3.out' }, 0);
    hoverTl.to(focusUniform, { value: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(hoverTl);
  };
  const onPointerLeave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: '-=0.15', duration: 0.3, ease: 'power3.out' }, 0);
    hoverTl.to(focusUniform, { value: 0.18, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(hoverTl);
  };
  const onPointerDown = () => {
    gsap.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
  };
  const onPointerUp = () => {
    gsap.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.15, ease: 'back.out(1.7)' });
  };
  const onClick = () => {
    ctx.emit('hub-journal.select', { nodeId: config.id ?? 'journal-quote-panel' });
  };

  root.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerover: onPointerEnter,
    pointerleave: onPointerLeave,
    pointerout: onPointerLeave,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick,
  };

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const fn of cleanupFns) {
      try { fn(); } catch (e) { /* noop */ }
    }
    root.traverse((obj) => {
      if (obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          if (m.map && m.map.dispose) m.map.dispose();
          if (m.dispose) m.dispose();
        }
      }
    });
    for (const d of disposables) {
      if (d && d.dispose) d.dispose();
    }
  };

  return root;
}
